// Simple English-keyed translation: t("...") returns the Spanish string when
// the visitor picked (or their browser speaks) Spanish, else the English key.
type Translate=(text:string)=>string;

type Team = { name:string; abbreviation:string; probablePitcher:string|null; starter:{playerId:number|null;era:number;innings:number;gamesStarted:number;runAdjustment:number;strikeOuts:number;expectedStrikeouts:number|null}|null; opponentStrikeoutRate:number|null; bullpen:{recentPitches:number;taxedRelievers:number;runAdjustment:number;sourceWindow?:string}; expectedRuns:number; winProbability:number; fairPrice:string };
type Hitter={id:number;name:string;battingOrder:number;confirmed:boolean;avg:string|null;ops:string|null;expectedHits:number|null;onePlusHitProbability:number|null;fairPrice:string|null;opposingHand?:string|null;platoonAtBats?:number|null;platoonAdjusted?:boolean};
type ProjectionGame = { id:number; startsAt:string|null; status:string; venue:string; park:{factor:number;priorGames:number;sourceCutoff:string}; weather:{condition:string|null;temperature:number|null;wind:string|null;roof:string|null}; quality:{teamRecords:boolean;starterStats:boolean;awayStarter:boolean;homeStarter:boolean;lineups:boolean;weather:boolean;parkSample:boolean;bullpen:boolean;opponentStrikeouts:boolean;platoon:boolean;validatedMarkets:{moneyline:boolean;total:boolean;firstFive:boolean;firstInning:boolean;pitcherStrikeouts:boolean;hitterHits:boolean};blockingReasons:string[]}; uncertainty:number; away:Team; home:Team; total:{line:number;lineSource?:string;expectedRuns:number;overProbability:number;underProbability:number;pushProbability?:number;overFairPrice:string;underFairPrice:string}; firstFive:{expectedRuns:number;awayWinProbability:number;homeWinProbability:number;pushProbability:number;awayFairPrice:string;homeFairPrice:string}; firstInning:{expectedRuns:number;nrfiProbability:number;yrfiProbability:number;nrfiFairPrice:string;yrfiFairPrice:string}; lineups:{away:Hitter[];home:Hitter[];confirmed:boolean}; drivers:string[]; recommendation:{reason:string} };
type ModelInfo={name:string;calibrated:boolean;calibrationScope?:string;calibrationPoints?:number;featureCutoff?:string;omissions:string[]};
type Coverage={available:number;expected:number};
type DataHealth={score:number;coverage:{teams:Coverage;starters:Coverage;lineups:Coverage;hitters:Coverage;weather:Coverage;parks:Coverage;bullpens:Coverage;opponentStrikeouts:Coverage;platoonSplits:Coverage;rosterStatuses:Coverage};featureCutoff:string;historicalFinals:number;calibrated:boolean;retrievedAt:string};
type Persistence={ok:boolean;forecasts:number;archives:number;error:string|null};
type ApiResponse = { games:ProjectionGame[]; retrievedAt:string; error?:string; model?:ModelInfo;dataHealth?:DataHealth;persistence?:Persistence };
type BacktestMarketMetric={count:number;accuracy:number|null;brier:number|null;logLoss:number|null};
type CalibrationMetrics={count:number;brier:number;logLoss:number;rawBrier:number;rawLogLoss:number;rawEce:number;selectedMethod:string;selectedBrier:number;selectedLogLoss:number;verified:boolean};
type Backtest = { gamesIngested:number; through:string; metrics:{count:number;accuracy:number|null;brier:number|null;logLoss:number|null;totalMae:number|null}; marketMetrics:{moneyline:BacktestMarketMetric;totalOver85:BacktestMarketMetric;firstFiveHome:BacktestMarketMetric;nrfi:BacktestMarketMetric}; calibratedMetrics:CalibrationMetrics|null;marketCalibratedMetrics:{totalOver85:CalibrationMetrics|null;firstFiveHome:CalibrationMetrics|null;nrfi:CalibrationMetrics|null}; calibration:Array<{low:number;high:number;count:number;predicted:number|null;actual:number|null}>; error?:string };
type ProspectivePerformance={issued:number;settledNow:number;status:Record<string,number>;total:{count:number;accuracy:number|null;brier:number|null};markets:Array<{market:string;count:number;accuracy:number|null;brier:number|null}>;bands:Array<{label:string;count:number;accuracy:number|null;brier:number|null}>};
type LedgerBet={id:string;game_id:number;game_date:string;starts_at:string|null;matchup:string;market:string;selection:string;selection_key:string|null;line:number|null;american_odds:number;max_playable_odds?:number|null;model_probability:number;edge:number;stake_units:number;mode?:string;decision?:string;status:string;profit_units:number|null;price_verified?:number;closing_odds:number|null;closing_opposite_odds:number|null;closing_line_value:number|null;created_at:string};
type ConsensusSide={medianAmerican:number;books:number;bestAmerican:number;bestBook:string;pairedOppositeAmerican:number|null}|null;
type ConsensusGame={homeTeam:string;awayTeam:string;bookmakers:number;moneyline:{home:ConsensusSide;away:ConsensusSide};total:{line:number;over:ConsensusSide;under:ConsensusSide}|null};
type OddsResponse={configured:boolean;provider:string;games:ConsensusGame[];retrievedAt?:string;message?:string};
