  const load=useCallback(async()=>{ const sequence=++loadSequence.current; setLoading(true); setError(null); try { const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10); const through=date<yesterday?date:yesterday; const historyPromise=fetch(`/api/mlb/backtest?through=${through}`,{cache:"no-store"}); void historyPromise.then(async historyResponse=>{if(sequence===loadSequence.current&&historyResponse.ok)setBacktest(await historyResponse.json() as Backtest);}).catch(()=>{}); const [response,oddsResponse,vaultResponse,marketResponse]=await Promise.all([fetch(`/api/mlb/projections?date=${date}`,{cache:"no-store"}),fetch("/api/odds",{cache:"no-store"}),fetch("/api/odds-vault",{cache:"no-store"}),fetch("/api/mlb/market-validation",{cache:"no-store"})]); const payload=await response.json() as ApiResponse; if(sequence!==loadSequence.current)return; if(!response.ok||payload.error) throw new Error(payload.error??"Unable to load projections"); setGames(payload.games);setModel(payload.model??null);setDataHealth(payload.dataHealth??null);setPersistence(payload.persistence??null); setUpdated(payload.retrievedAt); setSelected(current=>payload.games.some(game=>game.id===current)?current:null); void fetch("/api/mlb/forecast-performance",{cache:"no-store"}).then(async performanceResponse=>{if(sequence===loadSequence.current&&performanceResponse.ok)setProspective(await performanceResponse.json() as ProspectivePerformance);}).catch(()=>{}); if(oddsResponse.ok)setOddsFeed(await oddsResponse.json() as OddsResponse);if(vaultResponse.ok)setOddsVault(await vaultResponse.json() as OddsVault);if(marketResponse.ok)setMarketValidation(await marketResponse.json() as MarketValidation); } catch(reason) { if(sequence!==loadSequence.current)return; setGames([]);setModel(null);setDataHealth(null);setPersistence(null); setError(reason instanceof Error?reason.message:"Unable to load projections"); } finally { if(sequence===loadSequence.current)setLoading(false); } },[date]);
