  const loadLedger=useCallback(async(key:string,reconcile=false)=>{try{if(reconcile)await fetch("/api/ledger",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey:key})});const response=await fetch("/api/ledger",{cache:"no-store",headers:{"x-owner-key":key}});if(response.ok){const payload=await response.json() as {bets:LedgerBet[]};setLedger(payload.bets);}}catch{/* Ledger status remains non-blocking. */}},[]);
