  useEffect(()=>{const saved=localStorage.getItem("baseline-lang");if(saved==="es"||saved==="en")setLang(saved);else if(typeof navigator!=="undefined"&&navigator.language?.toLowerCase().startsWith("es"))setLang("es");},[]);
