  useEffect(()=>{setGuideOpen(localStorage.getItem("baseline-guide-dismissed")!=="yes");},[]);
  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem("baseline-view-preferences")??"{}");setPreferredMarkets(Array.isArray(saved.markets)?saved.markets:[]);setPreferredBooks(Array.isArray(saved.books)?saved.books:[]);}catch{}finally{setPreferencesReady(true);}},[]);
  useEffect(()=>{if(preferencesReady)localStorage.setItem("baseline-view-preferences",JSON.stringify({markets:preferredMarkets,books:preferredBooks}));},[preferencesReady,preferredMarkets,preferredBooks]);
  const dataGate=useMemo(()=>{if(!active)return{qualifies:false,reason:"Select a game."};const requiresBothStarters=!["hit","awayK","homeK"].includes(marketMode),validationKey=marketMode==="moneyline"?"moneyline":marketMode==="over"||marketMode==="under"?"total":marketMode==="f5"?"firstFive":marketMode==="nrfi"||marketMode==="yrfi"?"firstInning":marketMode==="awayK"||marketMode==="homeK"?"pitcherStrikeouts":"hitterHits",marketValidated=active.quality.validatedMarkets[validationKey];const hitters=[...active.lineups.away,...active.lineups.home],selectedHitter=hitters.find(hitter=>hitter.id===selectedHitterId)??hitters[0];const reasons=[!marketValidated?"This probability model has not passed market-specific walk-forward validation.":null,!active.quality.teamRecords?"Both team season records are required.":null,requiresBothStarters&&!active.quality.starterStats?"Both probable starters need official season statistics.":null,marketMode==="awayK"&&!active.quality.opponentStrikeouts?"Opponent team strikeout rate is required.":null,marketMode==="homeK"&&!active.quality.opponentStrikeouts?"Opponent team strikeout rate is required.":null,marketMode==="awayK"&&!active.quality.awayStarter?"The away starter needs an official season stat line.":null,marketMode==="homeK"&&!active.quality.homeStarter?"The home starter needs an official season stat line.":null,marketMode==="hit"&&!active.quality.lineups?"Confirmed batting orders are required for hit props.":null,marketMode==="hit"&&!selectedHitter?.platoonAdjusted?"A verified split against the opposing starter’s hand is required.":null].filter((reason):reason is string=>Boolean(reason));return{qualifies:reasons.length===0,reason:reasons[0]??"Required model inputs and market validation are available."};},[active,marketMode,selectedHitterId]);
  const savePaperDecision=useCallback(async()=>{if(!active||!priced||!ownerKey)return;setSaving(true);setLedgerMessage(null);const line=marketMode==="over"||marketMode==="under"?activeTotalLine:marketMode==="awayK"||marketMode==="homeK"?Number(propLine):null,moneylineHome=active.home.winProbability>=active.away.winProbability,firstFiveHome=active.firstFive.homeWinProbability>=active.firstFive.awayWinProbability,hitters=[...active.lineups.away,...active.lineups.home],hitter=hitters.find(player=>player.id===selectedHitterId)??hitters[0],selectionKey=marketMode==="moneyline"?(moneylineHome?"home":"away"):marketMode==="f5"?(firstFiveHome?"home":"away"):marketMode==="awayK"||marketMode==="homeK"?"over":marketMode==="hit"?"onePlus":marketMode,subjectId=marketMode==="awayK"?active.away.starter?.playerId??null:marketMode==="homeK"?active.home.starter?.playerId??null:marketMode==="hit"?hitter?.id??null:null;try{const response=await fetch("/api/ledger",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({paperMode:true,ownerKey,gameId:active.id,gameDate:date,startsAt:active.startsAt,matchup:`${active.away.abbreviation} @ ${active.home.abbreviation}`,market:marketMode,selection:priced.market.name,selectionKey,subjectId,line,americanOdds:Number(marketPrice),oppositeOdds:Number(oppositePrice),modelProbability:priced.market.probability,marketProbability:priced.marketProbability,edge:priced.edge,expectedValue:priced.expectedValue,stakeUnits:priced.stakeFraction,evidence:{dataGate:dataGate.reason,blockingReasons:active.quality.blockingReasons}})});const payload=await response.json() as {error?:string;bet?:{decision?:string}};if(!response.ok)throw new Error(payload.error??"Unable to freeze paper decision");setLedgerMessage(`${payload.bet?.decision??"Paper decision"} frozen with its entry price.`);await loadLedger(ownerKey);}catch(reason){setLedgerMessage(reason instanceof Error?reason.message:"Unable to freeze paper decision");}finally{setSaving(false);}},[active,activeTotalLine,priced,ownerKey,marketMode,propLine,date,marketPrice,oppositePrice,selectedHitterId,loadLedger,dataGate]);
  const removeBet=useCallback(async(id:string)=>{if(!ownerKey)return;await fetch(`/api/ledger?id=${encodeURIComponent(id)}`,{method:"DELETE",headers:{"x-owner-key":ownerKey}});await loadLedger(ownerKey);},[ownerKey,loadLedger]);
  const settleLedger=useCallback(async()=>{if(!ownerKey)return;setSettling(true);setLedgerMessage(null);try{const response=await fetch("/api/ledger",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey})});const payload=await response.json() as {settled?:number;error?:string};if(!response.ok)throw new Error(payload.error??"Unable to settle");setLedgerMessage(`${payload.settled??0} final recommendation${payload.settled===1?"":"s"} settled.`);await loadLedger(ownerKey);}catch(reason){setLedgerMessage(reason instanceof Error?reason.message:"Unable to settle recommendations");}finally{setSettling(false);}},[ownerKey,loadLedger]);
