  const useConsensus=useCallback(()=>{if(!active||!activeOdds)return;let selected:ConsensusSide=null,opposite:ConsensusSide=null;if(marketMode==="moneyline"){const homeFavorite=active.home.winProbability>=active.away.winProbability;selected=homeFavorite?activeOdds.moneyline.home:activeOdds.moneyline.away;opposite=homeFavorite?activeOdds.moneyline.away:activeOdds.moneyline.home;}else if(marketMode==="over"||marketMode==="under"){selected=marketMode==="over"?activeOdds.total?.over??null:activeOdds.total?.under??null;opposite=marketMode==="over"?activeOdds.total?.under??null:activeOdds.total?.over??null;}if(selected&&selected.pairedOppositeAmerican!=null){setMarketPrice(String(selected.bestAmerican));setOppositePrice(String(selected.pairedOppositeAmerican));}},[active,activeOdds,marketMode]);
  // Manual snapshots carry explicit canonical market/selection pairs so the
